import heapq
import math


def shortest_distance_km(graph, start, end):
    if not hasattr(graph, "items"):
        raise TypeError("graph must be a mapping")
    nodes = set(graph)
    if any(not isinstance(node, str) for node in nodes):
        raise TypeError("node names must be strings")
    if any(not node for node in nodes):
        raise ValueError("node names must not be empty")
    if start not in nodes or end not in nodes:
        raise ValueError("unknown endpoint")

    adjacency = {}
    for node, edges in graph.items():
        if not hasattr(edges, "items"):
            raise TypeError("adjacency values must be mappings")
        copied = []
        for neighbor, meters in edges.items():
            if neighbor not in nodes:
                raise ValueError("edge references an unknown node")
            if not isinstance(meters, (int, float)) or isinstance(meters, bool):
                raise TypeError("edge lengths must be numeric")
            if not math.isfinite(meters) or meters < 0:
                raise ValueError("edge lengths must be finite and non-negative")
            copied.append((neighbor, float(meters)))
        adjacency[node] = copied

    distances = {start: 0.0}
    queue = [(0.0, start)]
    while queue:
        distance, node = heapq.heappop(queue)
        if distance != distances.get(node):
            continue
        if node == end:
            return distance
        for neighbor, meters in adjacency[node]:
            candidate = distance + meters
            if candidate < distances.get(neighbor, math.inf):
                distances[neighbor] = candidate
                heapq.heappush(queue, (candidate, neighbor))
    return None
