import math
import unittest

from solution import shortest_distance_km


class ShortestDistanceTests(unittest.TestCase):
    def test_returns_shortest_distance_in_kilometers(self):
        graph = {
            "A": {"B": 700, "C": 2000},
            "B": {"C": 500},
            "C": {},
        }
        self.assertAlmostEqual(shortest_distance_km(graph, "A", "C"), 1.2)

    def test_fractional_and_zero_lengths(self):
        graph = {
            "A": {"B": 250.5},
            "B": {"C": 0},
            "C": {},
        }
        self.assertAlmostEqual(shortest_distance_km(graph, "A", "C"), 0.2505)

    def test_same_endpoint_is_zero(self):
        graph = {"A": {}}
        result = shortest_distance_km(graph, "A", "A")
        self.assertEqual(result, 0.0)
        self.assertIsInstance(result, float)

    def test_unreachable_returns_none(self):
        graph = {"A": {}, "B": {}}
        self.assertIsNone(shortest_distance_km(graph, "A", "B"))

    def test_graph_is_not_mutated(self):
        graph = {"A": {"B": 1000}, "B": {}}
        original = {"A": {"B": 1000}, "B": {}}
        shortest_distance_km(graph, "A", "B")
        self.assertEqual(graph, original)

    def test_rejects_invalid_graph_shapes_and_nodes(self):
        invalid_graphs = [
            [],
            {"": {}},
            {1: {}},
            {"A": []},
            {"A": {"B": 1}},
        ]
        for graph in invalid_graphs:
            with self.subTest(graph=graph):
                with self.assertRaises((TypeError, ValueError)):
                    shortest_distance_km(graph, "A", "A")

    def test_rejects_invalid_lengths(self):
        invalid_lengths = [True, False, -1, math.inf, -math.inf, math.nan, "10", None]
        for length in invalid_lengths:
            graph = {"A": {"B": length}, "B": {}}
            with self.subTest(length=length):
                with self.assertRaises((TypeError, ValueError)):
                    shortest_distance_km(graph, "A", "B")

    def test_unknown_endpoints_are_rejected(self):
        graph = {"A": {}}
        with self.assertRaises((TypeError, ValueError)):
            shortest_distance_km(graph, "missing", "A")
        with self.assertRaises((TypeError, ValueError)):
            shortest_distance_km(graph, "A", "missing")


if __name__ == "__main__":
    unittest.main()

